<?php
define('_GNUBOARD_',true);require __DIR__.'/../../bridge/home-core.php';require __DIR__.'/../../bridge/home-discovery.php';
function check($v,$m){if(!$v)throw new RuntimeException($m);}
$now=strtotime('2026-10-28T00:00:00Z');$rows=[];for($i=0;$i<12;$i++)$rows[]=['videoId'=>sprintf('video%06d',$i),'views'=>100-$i,'publishedAt'=>gmdate('c',$now-86400*(12-$i)),'genre'=>'kpop-original'];
$ranked=[['videoId'=>$rows[0]['videoId'],'score'=>999,'views'=>80]];$previous=[$rows[0]['videoId']=>90,$rows[5]['videoId']=>1,$rows[7]['videoId']=>10000];
$d=nh_discovery_build($rows,$ranked,$previous,86400,$now);check(count($d['mixed'])===8,'mixed count');check(count(array_unique(array_column($d['mixed'],'videoId')))===8,'duplicate mix');check(count(array_unique(array_column($d['mixed'],'recommendationKind')))===3,'missing variety');check($d['popular'][0]['score']===999,'integrated popularity lost');check($d['rising'][0]['videoId']===$rows[5]['videoId'],'growth order');check($d['rising'][1]['viewGain']===10,'latest views overwritten by ranking snapshot');check($d['new'][0]['videoId']===$rows[11]['videoId'],'published date order');
check(!nh_discovery_build($rows,$ranked,[],null,$now)['rising'],'fake trend without history');check(!nh_discovery_build($rows,$ranked,$previous,300000,$now)['rising'],'stale trend');
$bad=[['videoId'=>'future00001','views'=>0,'publishedAt'=>'2099-01-01'],['videoId'=>'unknown0001','views'=>0,'publishedAt'=>null]];check(!nh_discovery_build($bad,[],[],null,$now)['new'],'unknown/future publish date');
$channel='owner';$songs=['s'=>['genre_id'=>'kpop-original','ep'=>1]];$videos=[];foreach(['public','private']as $privacy)$videos[]=['id'=>$privacy==='public'?'public00001':'private0001','snippet'=>['channelId'=>$channel,'title'=>'song','publishedAt'=>'2026-10-27T00:00:00Z'],'status'=>['privacyStatus'=>$privacy,'embeddable'=>true],'statistics'=>['viewCount'=>'100'],'match'=>['songId'=>'s','status'=>'matched']];$data=nh_build($videos,$songs,[],[],$channel);check(array_column($data['discoveryCandidates'],'videoId')===['public00001'],'private candidate leaked');
echo "HOME_DISCOVERY_VARIETY_GROWTH_DATE_PRIVACY_OK\n";
